package assignment;

public class Main {
	static String city="Lodon";
	static int Population = 900000000;

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Main myobj = new Main();
		System.out.println("City name : "+myobj.city);
		System.out.println("Population : "+myobj.Population);
		System.out.println("With Static : ");
		System.out.println(city);
		System.out.println(Population);
		
		

	}

}
